tape( 'the function supports complex ndarrays (complex64)', function test( t ) {
	var expected;
	var actual;
	var alpha;
	var beta;
	var xbuf;
	var x;

	xbuf = new Complex64Array([
		1.0, // 0
		2.0, // 0
		3.0, // 1
		4.0, // 1
		5.0, // 2
		6.0, // 2
		7.0, // 3
		8.0  // 3
	]);
	x = new ndarray( 'complex64', xbuf, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	alpha = scalar2ndarray( new Complex64( 2.0, 0.0 ), {
		'dtype': 'complex64'
	});
	beta = scalar2ndarray( new Complex64( 1.0, 0.0 ), {
		'dtype': 'complex64'
	});

	actual = axpb( x, alpha, beta );

	expected = new Complex64Array([
		// 2.0*(1.0+2.0i) + 1.0
		3.0,
		4.0,
		// 2.0*(3.0+4.0i) + 1.0
		7.0,
		8.0,
		// 2.0*(5.0+6.0i) + 1.0
		11.0,
		12.0,
		// 2.0*(7.0+8.0i) + 1.0
		15.0,
		16.0
	]);
	t.strictEqual( actual, x, 'returns expected value' );
	t.strictEqual( String( getDType( actual ) ), 'complex64', 'returns expected value' );
	t.deepEqual( getShape( actual ), getShape( x ), 'returns expected value' );
	t.strictEqual( getOrder( actual ), getOrder( x ), 'returns expected value' );
	t.strictEqual( isSameComplex64Array( getData( actual ), expected ), true, 'returns expected value' );

	t.end();
});

